/// key returns the shared singleton.
WebEcho webEcho_createNativeInstance([String key = 'default']) =>
    _WebEchoImpl(key);

extension WebEchoNativeRef on WebEcho {
  AnyNativeObject get asAnyNativeObject =>
      (this as _WebEchoImpl).asAnyNativeObject;
}

/// Creates the native implementation of [WebEcho]. A distinct [key]
